<script setup lang="ts">import{computed,onUpdated}from'vue';import{marked}from'marked';import hljs from'highlight.js';const p=defineProps<{content:string}>();marked.use({renderer:{code({text,lang}){const language=lang&&hljs.getLanguage(lang)?lang:'plaintext';return`<pre><code class="hljs language-${language}">${hljs.highlight(text,{language}).value}</code></pre>`}}});const html=computed(()=>marked.parse(p.content));onUpdated(()=>{})</script><template><div class="prose" v-html="html"></div></template>
